# Generates clean UTF-8 story blocks from \u escapes (avoids editor corruption).
from pathlib import Path

te_title = "\u0c28\u0c26\u0c3f \u0c12\u0c21\u0c4d\u0c21\u0c41\u0c28 \u0c26\u0c4a\u0c30\u0c3f\u0c15\u0c3f\u0c28 \u0c2a\u0c41\u0c38\u0c4d\u0c24\u0c15\u0c02"
te = [
    "\u0c12\u0c15 \u0c28\u0c3f\u0c36\u0c4d\u0c36\u0c2c\u0c4d\u0c26 \u0c09\u0c26\u0c2f\u0c02 \u0c28\u0c42\u0c30\u0c4d \u0c05\u0c28\u0c47 \u0c2a\u0c3f\u0c32\u0c4d\u0c32\u0c35\u0c3e\u0c21\u0c41 \u0c2a\u0c3e\u0c24 \u0c2e\u0c3e\u0c30\u0c4d\u0c15\u0c46\u0c1f\u0c4d \u0c35\u0c46\u0c28\u0c41\u0c15 \u0c28\u0c26\u0c3f \u0c12\u0c21\u0c4d\u0c21\u0c41\u0c28 \u0c28\u0c21\u0c3f\u0c1a\u0c3e\u0c21\u0c41. \u0c28\u0c40\u0c30\u0c41 \u0c28\u0c46\u0c2e\u0c4d\u0c2e\u0c26\u0c3f\u0c17\u0c3e \u0c15\u0c26\u0c3f\u0c32\u0c3f\u0c02\u0c26\u0c3f. \u0c30\u0c46\u0c02\u0c21\u0c41 \u0c24\u0c21\u0c3f \u0c30\u0c3e\u0c33\u0c4d\u0c32 \u0c2e\u0c27\u0c4d\u0c2f \u0c2a\u0c47\u0c30\u0c41\u0c32\u0c47\u0c28\u0c3f \u0c2a\u0c41\u0c38\u0c4d\u0c24\u0c15\u0c02 \u0c26\u0c4a\u0c30\u0c3f\u0c15\u0c3f\u0c02\u0c26\u0c3f. \u0c2e\u0c4a\u0c26\u0c1f\u0c3f \u0c2a\u0c47\u0c1c\u0c40 \u0c24\u0c46\u0c30\u0c3f\u0c1a\u0c3f\u0c28\u0c2a\u0c4d\u0c2a\u0c41\u0c21\u0c41 \u0c05\u0c26\u0c3f \u0c35\u0c3e\u0c30\u0c3f \u0c2d\u0c3e\u0c37\u0c32\u0c4b \u0c2e\u0c3e\u0c1f\u0c4d\u0c32\u0c3e\u0c21\u0c3f\u0c02\u0c26\u0c3f. \u0c24\u0c30\u0c4d\u0c35\u0c3e\u0c24\u0c3f \u0c2a\u0c47\u0c1c\u0c40 \u0c2e\u0c3e\u0c30\u0c3f\u0c02\u0c26\u0c3f.",
    "\u0c28\u0c42\u0c30\u0c4d \u0c2e\u0c3e\u0c2e\u0c3f\u0c21\u0c3f \u0c1a\u0c46\u0c1f\u0c4d\u0c1f\u0c41 \u0c15\u0c3f\u0c02\u0c26 \u0c15\u0c42\u0c30\u0c4d\u0c1a\u0c41\u0c28\u0c3f \u0c1a\u0c26\u0c3f\u0c35\u0c3e\u0c21\u0c41. \u0c12\u0c15 \u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c3f \u0c0f\u0c02 \u0c1a\u0c26\u0c41\u0c35\u0c41\u0c24\u0c41\u0c28\u0c4d\u0c28\u0c3e\u0c30\u0c28\u0c3f \u0c05\u0c21\u0c3f\u0c17\u0c3e\u0c21\u0c41. \u0c28\u0c42\u0c30\u0c4d \u0c05\u0c28\u0c4d\u0c28\u0c3e\u0c21\u0c41, \u0c07\u0c26\u0c3f \u0c12\u0c15 \u0c2d\u0c3e\u0c37\u0c32\u0c4b \u0c09\u0c02\u0c21\u0c1f\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c28\u0c3f\u0c30\u0c3e\u0c15\u0c30\u0c3f\u0c02\u0c1a\u0c47 \u0c15\u0c25. \u0c15\u0c3e\u0c17\u0c3f\u0c24\u0c02 \u0c28\u0c41\u0c02\u0c1a\u0c3f \u0c05\u0c2e\u0c4d\u0c2e\u0c2e\u0c4d\u0c2e \u0c38\u0c4d\u0c35\u0c30\u0c02 \u0c32\u0c47\u0c1a\u0c3f\u0c02\u0c26\u0c3f.",
    "\u0c35\u0c3e\u0c30\u0c41 \u0c2a\u0c41\u0c38\u0c4d\u0c24\u0c15\u0c3e\u0c28\u0c4d\u0c28\u0c3f \u0c28\u0c17\u0c30\u0c02 \u0c05\u0c02\u0c24\u0c3e \u0c24\u0c40\u0c38\u0c41\u0c15\u0c46\u0c33\u0c4d\u0c32\u0c3e\u0c30\u0c41. \u0c1f\u0c40 \u0c26\u0c41\u0c15\u0c3e\u0c23\u0c02\u0c32\u0c4b \u0c12\u0c15 \u0c35\u0c3f\u0c26\u0c4d\u0c2f\u0c3e\u0c30\u0c4d\u0c25\u0c3f \u0c28\u0c2e\u0c38\u0c4d\u0c15\u0c3e\u0c30\u0c02 \u0c35\u0c3f\u0c28\u0c3f \u0c28\u0c35\u0c4d\u0c35\u0c3e\u0c21\u0c41. \u0c38\u0c4d\u0c1f\u0c47\u0c37\u0c28\u0c4d\u0c32\u0c4b \u0c12\u0c15 \u0c2f\u0c3e\u0c24\u0c4d\u0c30\u0c3f\u0c15\u0c41\u0c21\u0c41 \u0c15\u0c33\u0c4d\u0c32\u0c41 \u0c2e\u0c42\u0c38\u0c41\u0c15\u0c41\u0c28\u0c3f \u0c35\u0c3f\u0c28\u0c4d\u0c28\u0c3e\u0c21\u0c41. \u0c2a\u0c3e\u0c30\u0c4d\u0c15\u0c41\u0c32\u0c4b \u0c12\u0c15 \u0c35\u0c43\u0c26\u0c4d\u0c27\u0c41\u0c30\u0c3e\u0c32\u0c41 \u0c28\u0c42\u0c30\u0c4d \u0c15\u0c02\u0c1f\u0c47 \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c35\u0c3e\u0c15\u0c4d\u0c2f\u0c02 \u0c2a\u0c42\u0c30\u0c4d\u0c24\u0c3f \u0c1a\u0c47\u0c38\u0c3f\u0c02\u0c26\u0c3f.",
    "\u0c38\u0c3e\u0c2f\u0c02\u0c24\u0c4d\u0c30\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c1a\u0c3f\u0c35\u0c30\u0c3f \u0c2a\u0c47\u0c1c\u0c40 \u0c26\u0c3e\u0c26\u0c3e\u0c2a\u0c41 \u0c16\u0c3e\u0c33\u0c40\u0c17\u0c3e \u0c09\u0c02\u0c26\u0c3f. \u0c12\u0c15 \u0c35\u0c3e\u0c15\u0c4d\u0c2f\u0c02 \u0c2e\u0c3e\u0c24\u0c4d\u0c30\u0c2e\u0c47 \u0c2e\u0c3f\u0c17\u0c3f\u0c32\u0c3f\u0c02\u0c26\u0c3f. \u0c28\u0c41\u0c35\u0c4d\u0c35\u0c41 \u0c2a\u0c4d\u0c30\u0c47\u0c2e\u0c3f\u0c02\u0c1a\u0c47 \u0c2d\u0c3e\u0c37\u0c32\u0c4b \u0c24\u0c30\u0c4d\u0c35\u0c3e\u0c24\u0c3f \u0c2a\u0c47\u0c1c\u0c40 \u0c30\u0c3e\u0c2f\u0c3f. \u0c28\u0c42\u0c30\u0c4d \u0c28\u0c46\u0c2e\u0c4d\u0c2e\u0c26\u0c3f\u0c17\u0c3e \u0c30\u0c3e\u0c36\u0c3e\u0c21\u0c41. \u0c2a\u0c41\u0c38\u0c4d\u0c24\u0c15\u0c02 \u0c2e\u0c42\u0c38\u0c3f\u0c28\u0c2a\u0c4d\u0c2a\u0c41\u0c21\u0c41 \u0c28\u0c26\u0c3f \u0c35\u0c47\u0c32 \u0c17\u0c33\u0c3e\u0c32\u0c4d\u0c32\u0c3e \u0c35\u0c3f\u0c28\u0c3f\u0c2a\u0c3f\u0c02\u0c1a\u0c3f\u0c02\u0c26\u0c3f.",
    "\u0c06 \u0c30\u0c3e\u0c24\u0c4d\u0c30\u0c3f \u0c2e\u0c3e\u0c30\u0c4d\u0c15\u0c46\u0c1f\u0c4d \u0c26\u0c40\u0c2a\u0c3e\u0c32\u0c41 \u0c1a\u0c40\u0c15\u0c1f\u0c3f\u0c2a\u0c48 \u0c35\u0c3f\u0c30\u0c3e\u0c2e \u0c1a\u0c3f\u0c39\u0c4d\u0c28\u0c3e\u0c32\u0c4d\u0c32\u0c3e \u0c15\u0c28\u0c3f\u0c2a\u0c3f\u0c02\u0c1a\u0c3e\u0c2f\u0c3f. \u0c28\u0c42\u0c30\u0c4d \u0c12\u0c15 \u0c38\u0c30\u0c33\u0c2e\u0c48\u0c28 \u0c38\u0c24\u0c4d\u0c2f\u0c02 \u0c05\u0c30\u0c4d\u0c25\u0c02 \u0c1a\u0c47\u0c38\u0c41\u0c15\u0c41\u0c28\u0c4d\u0c28\u0c3e\u0c21\u0c41. \u0c2a\u0c26\u0c3e\u0c32\u0c41 \u0c05\u0c2f\u0c3f\u0c2a\u0c4b\u0c24\u0c47 \u0c15\u0c25 \u0c05\u0c2f\u0c3f\u0c2a\u0c4b\u0c26\u0c41. \u0c07\u0c02\u0c15\u0c4a\u0c15\u0c30\u0c41 \u0c26\u0c3e\u0c28\u0c4d\u0c28\u0c3f \u0c35\u0c3f\u0c28\u0c3f \u0c38\u0c2e\u0c3e\u0c27\u0c3e\u0c28\u0c02 \u0c1a\u0c46\u0c2a\u0c4d\u0c2a\u0c17\u0c32\u0c3f\u0c17\u0c3f\u0c28\u0c2a\u0c4d\u0c2a\u0c41\u0c21\u0c47 \u0c15\u0c25 \u0c2a\u0c42\u0c30\u0c4d\u0c24\u0c35\u0c41\u0c24\u0c41\u0c02\u0c26\u0c3f.",
]

ml_title = "\u0d28\u0d26\u0d3f\u0d15\u0d4d\u0d15\u0d30\u0d2f\u0d3f\u0d7d \u0d15\u0d3f\u0d1f\u0d4d\u0d1f\u0d3f\u0d2f \u0d2a\u0d41\u0d38\u0d4d\u0d24\u0d15\u0d02"
ml = [
    "\u0d12\u0d30\u0d41 \u0d28\u0d3f\u0d36\u0d2c\u0d4d\u0d26 \u0d2a\u0d4d\u0d30\u0d2d\u0d3e\u0d24\u0d24\u0d4d\u0d24\u0d3f\u0d7d \u0d28\u0d42\u0d7c \u0d0e\u0d28\u0d4d\u0d28 \u0d15\u0d41\u0d1f\u0d4d\u0d1f\u0d3f \u0d2a\u0d34\u0d2f \u0d1a\u0d28\u0d4d\u0d24\u0d2f\u0d41\u0d1f\u0d46 \u0d2a\u0d3f\u0d28\u0d4d\u0d28\u0d3f\u0d32\u0d41\u0d33\u0d4d\u0d33 \u0d28\u0d26\u0d3f\u0d15\u0d4d\u0d15\u0d30\u0d2f\u0d3f\u0d32\u0d42\u0d1f\u0d46 \u0d28\u0d1f\u0d28\u0d4d\u0d28\u0d41. \u0d35\u0d46\u0d33\u0d4d\u0d33\u0d02 \u0d2a\u0d24\u0d41\u0d15\u0d4d\u0d15\u0d46 \u0d12\u0d34\u0d41\u0d15\u0d3f. \u0d30\u0d23\u0d4d\u0d1f\u0d4d \u0d28\u0d28\u0d1e\u0d4d\u0d1e \u0d15\u0d32\u0d4d\u0d32\u0d41\u0d15\u0d7e\u0d15\u0d4d\u0d15\u0d3f\u0d1f\u0d2f\u0d3f\u0d7d \u0d2a\u0d47\u0d30\u0d3f\u0d32\u0d4d\u0d32\u0d3e\u0d24\u0d4d\u0d24 \u0d12\u0d30\u0d41 \u0d2a\u0d41\u0d38\u0d4d\u0d24\u0d15\u0d02 \u0d15\u0d3f\u0d1f\u0d4d\u0d1f\u0d3f. \u0d06\u0d26\u0d4d\u0d2f \u0d2a\u0d47\u0d1c\u0d4d \u0d24\u0d41\u0d31\u0d28\u0d4d\u0d28\u0d2a\u0d4d\u0d2a\u0d4b\u0d7e \u0d05\u0d24\u0d4d \u0d05\u0d35\u0d30\u0d41\u0d1f\u0d46 \u0d2d\u0d3e\u0d37\u0d2f\u0d3f\u0d7d \u0d38\u0d02\u0d38\u0d3e\u0d30\u0d3f\u0d1a\u0d4d\u0d1a\u0d41. \u0d05\u0d1f\u0d41\u0d24\u0d4d\u0d24 \u0d2a\u0d47\u0d1c\u0d4d \u0d2e\u0d3e\u0d31\u0d3f.",
    "\u0d28\u0d42\u0d7c \u0d2e\u0d3e\u0d35\u0d3f\u0d28\u0d4d\u0d31\u0d46 \u0d15\u0d40\u0d34\u0d3f\u0d7d \u0d07\u0d30\u0d41\u0d28\u0d4d\u0d28\u0d41 \u0d35\u0d3e\u0d2f\u0d3f\u0d1a\u0d4d\u0d1a\u0d41. \u0d12\u0d30\u0d41 \u0d35\u0d4d\u0d2f\u0d3e\u0d2a\u0d3e\u0d30\u0d3f \u0d0e\u0d28\u0d4d\u0d24\u0d3e\u0d23\u0d4d \u0d35\u0d3e\u0d2f\u0d3f\u0d15\u0d4d\u0d15\u0d41\u0d28\u0d4d\u0d28\u0d24\u0d46\u0d28\u0d4d\u0d28\u0d4d \u0d1a\u0d4b\u0d26\u0d3f\u0d1a\u0d4d\u0d1a\u0d41. \u0d28\u0d42\u0d7c \u0d2a\u0d31\u0d1e\u0d4d\u0d1e\u0d41, \u0d12\u0d30\u0d41 \u0d2d\u0d3e\u0d37\u0d2f\u0d3f\u0d7d \u0d28\u0d3f\u0d7d\u0d15\u0d4d\u0d15\u0d3e\u0d7b \u0d35\u0d3f\u0d38\u0d2e\u0d4d\u0d2e\u0d24\u0d3f\u0d15\u0d4d\u0d15\u0d41\u0d28\u0d4d\u0d28 \u0d12\u0d30\u0d41 \u0d15\u0d25. \u0d15\u0d1f\u0d32\u0d3e\u0d38\u0d3f\u0d7d \u0d28\u0d3f\u0d28\u0d4d\u0d28\u0d4d \u0d2e\u0d41\u0d24\u0d4d\u0d24\u0d36\u0d4d\u0d36\u0d3f\u0d2f\u0d41\u0d1f\u0d46 \u0d36\u0d2c\u0d4d\u0d26\u0d02 \u0d09\u0d2f\u0d7c\u0d28\u0d4d\u0d28\u0d41.",
    "\u0d05\u0d35\u0d7c \u0d2a\u0d41\u0d38\u0d4d\u0d24\u0d15\u0d02 \u0d28\u0d17\u0d30\u0d24\u0d4d\u0d24\u0d3f\u0d32\u0d42\u0d1f\u0d46 \u0d15\u0d4a\u0d23\u0d4d\u0d1f\u0d41\u0d2a\u0d4b\u0d2f\u0d3f. \u0d1a\u0d3e\u0d2f\u0d15\u0d4d\u0d15\u0d1f\u0d2f\u0d3f\u0d7d \u0d12\u0d30\u0d41 \u0d35\u0d3f\u0d26\u0d4d\u0d2f\u0d3e\u0d7c\u0d24\u0d4d\u0d25\u0d3f \u0d2a\u0d41\u0d1e\u0d4d\u0d1a\u0d3f\u0d30\u0d3f\u0d1a\u0d4d\u0d1a\u0d41. \u0d38\u0d4d\u0d31\u0d4d\u0d31\u0d47\u0d37\u0d28\u0d3f\u0d7d \u0d12\u0d30\u0d41 \u0d2f\u0d3e\u0d24\u0d4d\u0d30\u0d15\u0d4d\u0d15\u0d3e\u0d30\u0d7b \u0d15\u0d23\u0d4d\u0d23\u0d1f\u0d1a\u0d4d\u0d1a\u0d4d \u0d15\u0d47\u0d1f\u0d4d\u0d1f\u0d41. \u0d2a\u0d3e\u0d7c\u0d15\u0d4d\u0d15\u0d3f\u0d7d \u0d12\u0d30\u0d41 \u0d35\u0d43\u0d26\u0d4d\u0d27 \u0d28\u0d42\u0d31\u0d3f\u0d28\u0d4d \u0d2e\u0d41\u0d2e\u0d4d\u0d2a\u0d4d \u0d35\u0d3e\u0d15\u0d4d\u0d2f\u0d02 \u0d2a\u0d42\u0d7c\u0d24\u0d4d\u0d24\u0d3f\u0d2f\u0d3e\u0d15\u0d4d\u0d15\u0d3f.",
    "\u0d35\u0d48\u0d15\u0d41\u0d28\u0d4d\u0d28\u0d47\u0d30\u0d2e\u0d3e\u0d2f\u0d2a\u0d4d\u0d2a\u0d4b\u0d7e \u0d05\u0d35\u0d38\u0d3e\u0d28 \u0d2a\u0d47\u0d1c\u0d4d \u0d0f\u0d15\u0d26\u0d47\u0d36\u0d02 \u0d36\u0d42\u0d28\u0d4d\u0d2f\u0d2e\u0d3e\u0d2f\u0d3f\u0d30\u0d41\u0d28\u0d4d\u0d28\u0d41. \u0d12\u0d30\u0d41 \u0d35\u0d30\u0d3f \u0d2e\u0d3e\u0d24\u0d4d\u0d30\u0d02. \u0d28\u0d40 \u0d38\u0d4d\u0d28\u0d47\u0d39\u0d3f\u0d15\u0d4d\u0d15\u0d41\u0d28\u0d4d\u0d28 \u0d2d\u0d3e\u0d37\u0d2f\u0d3f\u0d7d \u0d05\u0d1f\u0d41\u0d24\u0d4d\u0d24 \u0d2a\u0d47\u0d1c\u0d4d \u0d0e\u0d34\u0d41\u0d24\u0d41\u0d15. \u0d28\u0d42\u0d7c \u0d2a\u0d24\u0d41\u0d15\u0d4d\u0d15\u0d46 \u0d0e\u0d34\u0d41\u0d24\u0d3f. \u0d2a\u0d41\u0d38\u0d4d\u0d24\u0d15\u0d02 \u0d05\u0d1f\u0d1a\u0d4d\u0d1a\u0d2a\u0d4d\u0d2a\u0d4b\u0d7e \u0d28\u0d26\u0d3f \u0d06\u0d2f\u0d3f\u0d30\u0d02 \u0d36\u0d2c\u0d4d\u0d26\u0d19\u0d4d\u0d19\u0d33\u0d46\u0d2a\u0d4d\u0d2a\u0d4b\u0d32\u0d46 \u0d15\u0d47\u0d1f\u0d4d\u0d1f\u0d41.",
    "\u0d06 \u0d30\u0d3e\u0d24\u0d4d\u0d30\u0d3f \u0d1a\u0d28\u0d4d\u0d24\u0d2f\u0d3f\u0d32\u0d46 \u0d35\u0d3f\u0d33\u0d15\u0d4d\u0d15\u0d41\u0d15\u0d7e \u0d07\u0d30\u0d41\u0d1f\u0d4d\u0d1f\u0d3f\u0d7d \u0d35\u0d3f\u0d30\u0d3e\u0d2e\u0d1a\u0d3f\u0d39\u0d4d\u0d28\u0d19\u0d4d\u0d19\u0d7e \u0d2a\u0d4b\u0d32\u0d46 \u0d24\u0d4b\u0d28\u0d4d\u0d28\u0d3f. \u0d28\u0d42\u0d7c \u0d12\u0d30\u0d41 \u0d32\u0d33\u0d3f\u0d24\u0d35\u0d41\u0d02 \u0d35\u0d32\u0d41\u0d24\u0d41\u0d2e\u0d3e\u0d2f \u0d15\u0d3e\u0d30\u0d4d\u0d2f\u0d02 \u0d2e\u0d28\u0d38\u0d4d\u0d38\u0d3f\u0d32\u0d3e\u0d15\u0d4d\u0d15\u0d3f. \u0d35\u0d3e\u0d15\u0d4d\u0d15\u0d41\u0d15\u0d7e \u0d24\u0d40\u0d30\u0d41\u0d2e\u0d4d\u0d2a\u0d4b\u0d7e \u0d15\u0d25 \u0d24\u0d40\u0d30\u0d41\u0d28\u0d4d\u0d28\u0d3f\u0d32\u0d4d\u0d32. \u0d2e\u0d31\u0d4d\u0d31\u0d4a\u0d30\u0d3e\u0d7e\u0d15\u0d4d\u0d15\u0d4d \u0d05\u0d24\u0d4d \u0d15\u0d47\u0d1f\u0d4d\u0d1f\u0d4d \u0d2e\u0d31\u0d41\u0d2a\u0d1f\u0d3f \u0d2a\u0d31\u0d2f\u0d3e\u0d7b \u0d15\u0d34\u0d3f\u0d2f\u0d41\u0d2e\u0d4d\u0d2a\u0d4b\u0d34\u0d3e\u0d23\u0d4d \u0d15\u0d25 \u0d2a\u0d42\u0d7c\u0d24\u0d4d\u0d24\u0d3f\u0d2f\u0d3e\u0d15\u0d41\u0d28\u0d4d\u0d28\u0d24\u0d4d.",
]

gu_title = "\u0aa8\u0aa6\u0ac0 \u0a95\u0abf\u0aa8\u0abe\u0ab0\u0ac7 \u0aae\u0ab3\u0ac7\u0ab2\u0ac1\u0a82 \u0aaa\u0ac1\u0ab8\u0acd\u0aa4\u0a95"
gu = [
    "\u0a8f\u0a95 \u0ab6\u0abe\u0a82\u0aa4 \u0ab8\u0ab5\u0abe\u0ab0\u0ac7 \u0aa8\u0ac2\u0ab0 \u0aa8\u0abe\u0aae\u0aa8\u0ac1\u0a82 \u0aac\u0abe\u0ab3\u0a95 \u0a9c\u0ac2\u0aa8\u0abe \u0aac\u0a9c\u0abe\u0ab0 \u0aaa\u0abe\u0a9b\u0ab3 \u0aa8\u0aa6\u0ac0 \u0a95\u0abf\u0aa8\u0abe\u0ab0\u0ac7 \u0a9a\u0abe\u0ab2\u0aa4\u0ac1\u0a82 \u0ab9\u0aa4\u0ac1\u0a82. \u0aaa\u0abe\u0aa3\u0ac0 \u0aa7\u0ac0\u0aae\u0ac7 \u0ab5\u0ab9\u0ac7\u0aa4\u0ac1\u0a82 \u0ab9\u0aa4\u0ac1\u0a82. \u0aac\u0ac7 \u0aad\u0ac0\u0aa8\u0abe \u0aaa\u0aa5\u0acd\u0aa5\u0ab0 \u0ab5\u0a9a\u0acd\u0a9a\u0ac7 \u0a8f\u0a95 \u0aaa\u0ac1\u0ab8\u0acd\u0aa4\u0a95 \u0aae\u0ab3\u0acd\u0aaf\u0ac1\u0a82 \u0a9c\u0ac7\u0aa8\u0abe \u0a95\u0ab5\u0ab0 \u0aaa\u0ab0 \u0ab6\u0ac0\u0ab0\u0acd\u0ab7\u0a95 \u0aa8\u0ab9\u0acb\u0aa4\u0ac1\u0a82. \u0aaa\u0ab9\u0ac7\u0ab2\u0ac1\u0a82 \u0aaa\u0abe\u0aa8\u0ac1\u0a82 \u0a96\u0ac2\u0ab2\u0acd\u0aaf\u0ac1\u0a82 \u0aa4\u0acb \u0aa4\u0ac7 \u0aa4\u0ac7\u0aae\u0aa8\u0ac0 \u0aad\u0abe\u0ab7\u0abe\u0aae\u0abe\u0a82 \u0aac\u0acb\u0ab2\u0acd\u0aaf\u0ac1\u0a82. \u0a86\u0a97\u0ab2\u0ac1\u0a82 \u0aaa\u0abe\u0aa8\u0ac1\u0a82 \u0aac\u0aa6\u0ab2\u0abe\u0aaf\u0ac1\u0a82.",
    "\u0aa8\u0ac2\u0ab0 \u0a95\u0ac7\u0ab0\u0ac0\u0aa8\u0abe \u0a9d\u0abe\u0aa1 \u0aa8\u0ac0\u0a9a\u0ac7 \u0aac\u0ac7\u0ab8\u0ac0\u0aa8\u0ac7 \u0ab5\u0abe\u0a82\u0a9a\u0acd\u0aaf\u0ac1\u0a82. \u0a8f\u0a95 \u0ab5\u0ac7\u0aaa\u0abe\u0ab0\u0ac0\u0a8f \u0aaa\u0ac2\u0a9b\u0acd\u0aaf\u0ac1\u0a82 \u0a95\u0ac7 \u0ab6\u0ac1\u0a82 \u0ab5\u0abe\u0a82\u0a9a\u0acb \u0a9b\u0acb. \u0aa8\u0ac2\u0ab0\u0ac7 \u0a95\u0ab9\u0acd\u0aaf\u0ac1\u0a82, \u0a8f\u0ab5\u0ac0 \u0ab5\u0abe\u0ab0\u0acd\u0aa4\u0abe \u0a9c\u0ac7 \u0a8f\u0a95 \u0aad\u0abe\u0ab7\u0abe\u0aae\u0abe\u0a82 \u0ab0\u0ab9\u0ac7\u0ab5\u0abe \u0aae\u0abe\u0a97\u0aa4\u0ac0 \u0aa8\u0aa5\u0ac0. \u0ab5\u0ac7\u0aaa\u0abe\u0ab0\u0ac0 \u0ab9\u0ab8\u0acd\u0aaf\u0acb. \u0aaa\u0a9b\u0ac0 \u0a95\u0abe\u0a97\u0ab3\u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0aa6\u0abe\u0aa6\u0ac0\u0aa8\u0acb \u0a85\u0ab5\u0abe\u0a9c \u0a8a\u0aa0\u0acd\u0aaf\u0acb.",
    "\u0aa4\u0ac7\u0a93 \u0aaa\u0ac1\u0ab8\u0acd\u0aa4\u0a95 \u0ab2\u0a88\u0aa8\u0ac7 \u0ab6\u0ab9\u0ac7\u0ab0 \u0aab\u0ab0\u0acd\u0aaf\u0abe. \u0a9a\u0abe\u0aa8\u0ac0 \u0aa6\u0ac1\u0a95\u0abe\u0aa8\u0aae\u0abe\u0a82 \u0a8f\u0a95 \u0ab5\u0abf\u0aa6\u0acd\u0aaf\u0abe\u0ab0\u0acd\u0aa5\u0ac0\u0a8f \u0ab8\u0acd\u0aae\u0abf\u0aa4 \u0a95\u0ab0\u0acd\u0aaf\u0ac1\u0a82. \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aaa\u0ab0 \u0a8f\u0a95 \u0aae\u0ac1\u0ab8\u0abe\u0aab\u0ab0\u0ac7 \u0a86\u0a82\u0a96\u0acb \u0aac\u0a82\u0aa7 \u0a95\u0ab0\u0ac0. \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0aae\u0abe\u0a82 \u0a8f\u0a95 \u0ab5\u0ac3\u0aa6\u0acd\u0aa7\u0abe\u0a8f \u0aa8\u0ac2\u0ab0\u0aa5\u0ac0 \u0aaa\u0ab9\u0ac7\u0ab2\u0abe\u0a82 \u0ab5\u0abe\u0a95\u0acd\u0aaf \u0aaa\u0ac2\u0ab0\u0ac1\u0a82 \u0a95\u0ab0\u0acd\u0aaf\u0ac1\u0a82.",
    "\u0ab8\u0abe\u0a82\u0a9c \u0ab8\u0ac1\u0aa7\u0ac0 \u0a9b\u0ac7\u0ab2\u0acd\u0ab2\u0ac1\u0a82 \u0aaa\u0abe\u0aa8\u0ac1\u0a82 \u0ab2\u0a97\u0aad\u0a97 \u0a96\u0abe\u0ab2\u0ac0 \u0ab9\u0aa4\u0ac1\u0a82. \u0aae\u0abe\u0aa4\u0acd\u0ab0 \u0a8f\u0a95 \u0ab2\u0ac0\u0a9f\u0ac0 \u0aac\u0a9a\u0ac0. \u0a9c\u0ac7 \u0aad\u0abe\u0ab7\u0abe \u0aa4\u0ac1\u0a82 \u0a9a\u0abe\u0ab9\u0ac7 \u0a9b\u0ac7 \u0aa4\u0ac7\u0aae\u0abe\u0a82 \u0a86\u0a97\u0ab2\u0ac1\u0a82 \u0aaa\u0abe\u0aa8\u0ac1\u0a82 \u0ab2\u0a96. \u0aa8\u0ac2\u0ab0\u0ac7 \u0aa7\u0ac0\u0aae\u0ac7 \u0ab2\u0a96\u0acd\u0aaf\u0ac1\u0a82. \u0aaa\u0ac1\u0ab8\u0acd\u0aa4\u0a95 \u0aac\u0a82\u0aa7 \u0a95\u0ab0\u0aa4\u0abe\u0a82 \u0aa8\u0aa6\u0ac0 \u0ab9\u0a9c\u0abe\u0ab0 \u0a85\u0ab5\u0abe\u0a9c\u0acb \u0a9c\u0ac7\u0ab5\u0ac0 \u0ab2\u0abe\u0a97\u0ac0.",
    "\u0aa4\u0ac7 \u0ab0\u0abe\u0aa4\u0acd\u0ab0\u0ac7 \u0aac\u0a9c\u0abe\u0ab0\u0aa8\u0abe \u0aa6\u0ac0\u0ab5\u0abe \u0a85\u0a82\u0aa7\u0a95\u0abe\u0ab0 \u0aaa\u0ab0 \u0ab5\u0abf\u0ab0\u0abe\u0aae\u0a9a\u0abf\u0ab9\u0acd\u0aa8\u0acb \u0a9c\u0ac7\u0ab5\u0abe \u0aa6\u0ac7\u0a96\u0abe\u0aaf\u0abe. \u0aa8\u0ac2\u0ab0\u0ac7 \u0a8f\u0a95 \u0ab8\u0abe\u0aa6\u0ac0 \u0ab5\u0abe\u0aa4 \u0ab8\u0aae\u0a9c\u0ac0. \u0ab6\u0aac\u0acd\u0aa6\u0acb \u0aaa\u0ac2\u0ab0\u0abe \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab0\u0acd\u0aa4\u0abe \u0aaa\u0ac2\u0ab0\u0ac0 \u0aa5\u0aa4\u0ac0 \u0aa8\u0aa5\u0ac0. \u0aac\u0ac0\u0a9c\u0acb \u0a95\u0acb\u0a88 \u0ab8\u0abe\u0a82\u0aad\u0ab3\u0ac0\u0aa8\u0ac7 \u0a9c\u0ab5\u0abe\u0aac \u0a86\u0aaa\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab0\u0acd\u0aa4\u0abe \u0aaa\u0ac2\u0ab0\u0ac0 \u0aa5\u0abe\u0aaf \u0a9b\u0ac7.",
]

pa_title = "\u0a28\u0a26\u0a40 \u0a15\u0a70\u0a22\u0a47 \u0a2e\u0a3f\u0a32\u0a40 \u0a15\u0a3f\u0a24\u0a3e\u0a2c"
pa = [
    "\u0a07\u0a71\u0a15 \u0a36\u0a3e\u0a02\u0a24 \u0a38\u0a35\u0a47\u0a30 \u0a28\u0a42\u0a30 \u0a28\u0a3e\u0a02 \u0a26\u0a3e \u0a2c\u0a71\u0a1a\u0a3e \u0a2a\u0a41\u0a30\u0a3e\u0a23\u0a47 \u0a2c\u0a3e\u0a1c\u0a3c\u0a3e\u0a30 \u0a2a\u0a3f\u0a71\u0a1b\u0a47 \u0a28\u0a26\u0a40 \u0a15\u0a70\u0a22\u0a47 \u0a24\u0a41\u0a30 \u0a30\u0a3f\u0a39\u0a3e \u0a38\u0a40. \u0a2a\u0a3e\u0a23\u0a40 \u0a39\u0a4c\u0a32\u0a40 \u0a35\u0a17\u0a26\u0a3e \u0a38\u0a40. \u0a26\u0a4b \u0a17\u0a3f\u0a71\u0a32\u0a47 \u0a2a\u0a71\u0a25\u0a30\u0a3e\u0a02 \u0a35\u0a3f\u0a1a\u0a15\u0a3e\u0a30 \u0a07\u0a71\u0a15 \u0a15\u0a3f\u0a24\u0a3e\u0a2c \u0a2e\u0a3f\u0a32\u0a40 \u0a1c\u0a3f\u0a38 \u0a26\u0a47 \u0a15\u0a35\u0a30 \u0a24\u0a47 \u0a38\u0a3f\u0a30\u0a32\u0a47\u0a16 \u0a28\u0a39\u0a40\u0a02 \u0a38\u0a40. \u0a2a\u0a39\u0a3f\u0a32\u0a3e \u0a2a\u0a70\u0a28\u0a3e \u0a16\u0a41\u0a32\u0a3f\u0a06 \u0a24\u0a3e\u0a02 \u0a09\u0a39 \u0a09\u0a28\u0a4d\u0a39\u0a3e\u0a02 \u0a26\u0a40 \u0a2d\u0a3e\u0a38\u0a3c\u0a3e \u0a35\u0a3f\u0a1a \u0a2c\u0a4b\u0a32\u0a40. \u0a05\u0a17\u0a32\u0a3e \u0a2a\u0a70\u0a28\u0a3e \u0a2c\u0a26\u0a32 \u0a17\u0a3f\u0a06.",
    "\u0a28\u0a42\u0a30 \u0a05\u0a70\u0a2c \u0a26\u0a47 \u0a30\u0a41\u0a71\u0a16 \u0a39\u0a47\u0a20 \u0a2c\u0a48\u0a20 \u0a15\u0a47 \u0a2a\u0a5c\u0a4d\u0a39\u0a26\u0a3e \u0a30\u0a3f\u0a39\u0a3e. \u0a07\u0a71\u0a15 \u0a35\u0a2a\u0a3e\u0a30\u0a40 \u0a28\u0a47 \u0a2a\u0a41\u0a71\u0a1b\u0a3f\u0a06 \u0a09\u0a39 \u0a15\u0a40 \u0a2a\u0a5c\u0a4d\u0a39 \u0a30\u0a39\u0a47 \u0a39\u0a28. \u0a28\u0a42\u0a30 \u0a28\u0a47 \u0a15\u0a3f\u0a39\u0a3e, \u0a07\u0a71\u0a15 \u0a10\u0a38\u0a40 \u0a15\u0a39\u0a3e\u0a23\u0a40 \u0a1c\u0a4b \u0a07\u0a71\u0a15 \u0a2d\u0a3e\u0a38\u0a3c\u0a3e \u0a35\u0a3f\u0a1a \u0a30\u0a39\u0a3f\u0a23\u0a3e \u0a28\u0a39\u0a40\u0a02 \u0a1a\u0a3e\u0a39\u0a41\u0a70\u0a26\u0a40. \u0a35\u0a2a\u0a3e\u0a30\u0a40 \u0a39\u0a71\u0a38\u0a3f\u0a06. \u0a2b\u0a3f\u0a30 \u0a15\u0a3e\u0a17\u0a1c\u0a3c \u0a24\u0a4b\u0a02 \u0a26\u0a3e\u0a26\u0a40 \u0a26\u0a40 \u0a06\u0a35\u0a3e\u0a1c\u0a3c \u0a09\u0a71\u0a20\u0a40.",
    "\u0a09\u0a39 \u0a15\u0a3f\u0a24\u0a3e\u0a2c \u0a32\u0a48 \u0a15\u0a47 \u0a38\u0a3c\u0a39\u0a3f\u0a30 \u0a18\u0a41\u0a70\u0a2e\u0a47. \u0a1a\u0a3e\u0a39 \u0a26\u0a40 \u0a39\u0a71\u0a1f\u0a40 \u0a35\u0a3f\u0a1a \u0a07\u0a71\u0a15 \u0a35\u0a3f\u0a26\u0a3f\u0a06\u0a30\u0a25\u0a40 \u0a2e\u0a41\u0a38\u0a15\u0a30\u0a3e\u0a07\u0a06. \u0a38\u0a1f\u0a47\u0a38\u0a3c\u0a28 \u0a24\u0a47 \u0a07\u0a71\u0a15 \u0a2f\u0a3e\u0a24\u0a30\u0a40 \u0a28\u0a47 \u0a05\u0a71\u0a16\u0a3e\u0a02 \u0a2c\u0a70\u0a26 \u0a15\u0a30 \u0a32\u0a08\u0a06\u0a02. \u0a2a\u0a3e\u0a30\u0a15 \u0a35\u0a3f\u0a1a \u0a07\u0a71\u0a15 \u0a2c\u0a1c\u0a3c\u0a41\u0a30\u0a17 \u0a14\u0a30\u0a24 \u0a28\u0a47 \u0a28\u0a42\u0a30 \u0a24\u0a4b\u0a02 \u0a2a\u0a39\u0a3f\u0a32\u0a3e\u0a02 \u0a35\u0a3e\u0a15 \u0a2a\u0a42\u0a30\u0a3e \u0a15\u0a30 \u0a26\u0a3f\u0a71\u0a24\u0a3e.",
    "\u0a38\u0a3c\u0a3e\u0a2e \u0a24\u0a71\u0a15 \u0a06\u0a16\u0a30\u0a40 \u0a2a\u0a70\u0a28\u0a3e \u0a32\u0a17\u0a2d\u0a17 \u0a16\u0a3e\u0a32\u0a40 \u0a38\u0a40. \u0a38\u0a3f\u0a30\u0a2b\u0a3c \u0a07\u0a71\u0a15 \u0a32\u0a3e\u0a08\u0a28 \u0a2c\u0a1a\u0a40. \u0a1c\u0a3f\u0a38 \u0a2d\u0a3e\u0a38\u0a3c\u0a3e \u0a28\u0a42\u0a70 \u0a24\u0a42\u0a70 \u0a2a\u0a3f\u0a06\u0a30 \u0a15\u0a30\u0a26\u0a3e \u0a39\u0a48\u0a02 \u0a09\u0a38 \u0a35\u0a3f\u0a1a \u0a05\u0a17\u0a32\u0a3e \u0a2a\u0a70\u0a28\u0a3e \u0a32\u0a3f\u0a16. \u0a28\u0a42\u0a30 \u0a28\u0a47 \u0a39\u0a4c\u0a32\u0a40 \u0a32\u0a3f\u0a16\u0a3f\u0a06. \u0a15\u0a3f\u0a24\u0a3e\u0a2c \u0a2c\u0a70\u0a26 \u0a15\u0a30\u0a26\u0a3f\u0a06\u0a02 \u0a28\u0a26\u0a40 \u0a39\u0a1c\u0a3c\u0a3e\u0a30\u0a3e\u0a02 \u0a06\u0a35\u0a3e\u0a1c\u0a3c\u0a3e\u0a02 \u0a35\u0a3e\u0a02\u0a17 \u0a32\u0a71\u0a17\u0a40.",
    "\u0a09\u0a38 \u0a30\u0a3e\u0a24 \u0a2c\u0a3e\u0a1c\u0a3c\u0a3e\u0a30 \u0a26\u0a40\u0a06\u0a02 \u0a32\u0a3e\u0a08\u0a1f\u0a3e\u0a02 \u0a39\u0a28\u0a47\u0a30\u0a47 \u0a09\u0a71\u0a24\u0a47 \u0a35\u0a3f\u0a30\u0a3e\u0a2e \u0a1a\u0a3f\u0a70\u0a28\u0a4d\u0a39\u0a3e\u0a02 \u0a35\u0a3e\u0a02\u0a17 \u0a26\u0a3f\u0a38\u0a40\u0a06\u0a02. \u0a28\u0a42\u0a30 \u0a28\u0a47 \u0a07\u0a71\u0a15 \u0a38\u0a3e\u0a26\u0a40 \u0a17\u0a71\u0a32 \u0a38\u0a2e\u0a1d\u0a40. \u0a38\u0a3c\u0a2c\u0a26 \u0a16\u0a24\u0a2e \u0a39\u0a4b\u0a23 \u0a28\u0a3e\u0a32 \u0a15\u0a39\u0a3e\u0a23\u0a40 \u0a16\u0a24\u0a2e \u0a28\u0a39\u0a40\u0a02 \u0a39\u0a41\u0a70\u0a26\u0a40. \u0a15\u0a39\u0a3e\u0a23\u0a40 \u0a24\u0a26 \u0a2a\u0a42\u0a30\u0a40 \u0a39\u0a41\u0a70\u0a26\u0a40 \u0a39\u0a48 \u0a1c\u0a26\u0a4b\u0a02 \u0a15\u0a4b\u0a08 \u0a39\u0a4b\u0a30 \u0a09\u0a38 \u0a28\u0a42\u0a70 \u0a38\u0a41\u0a23 \u0a38\u0a15\u0a47 \u0a24\u0a47 \u0a1c\u0a35\u0a3e\u0a2c \u0a26\u0a47 \u0a38\u0a15\u0a47.",
]

kn_title = "\u0ca8\u0ca6\u0cbf \u0ca6\u0ca1\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0cb8\u0cbf\u0c95\u0ccd\u0c95 \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95"
kn = [
    "\u0c92\u0c82\u0ca6\u0cc1 \u0ca8\u0cbf\u0cb6\u0ccd\u0cb6\u0cac\u0ccd\u0ca6 \u0cac\u0cc6\u0cb3\u0c97\u0ccd\u0c97\u0cc6 \u0ca8\u0cc2\u0cb0\u0ccd \u0c8e\u0c82\u0cac \u0cae\u0c97\u0cc1 \u0cb9\u0cb3\u0cc6\u0caf \u0cae\u0cbe\u0cb0\u0cc1\u0c95\u0c9f\u0ccd\u0c9f\u0cc6\u0caf \u0cb9\u0cbf\u0c82\u0ca6\u0cc6 \u0ca8\u0ca6\u0cbf \u0ca6\u0ca1\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0ca8\u0ca1\u0cc6\u0caf\u0cbf\u0ca4\u0cc1. \u0ca8\u0cc0\u0cb0\u0cc1 \u0ca8\u0cbf\u0ca7\u0cbe\u0ca8\u0cb5\u0cbe\u0c97\u0cbf \u0cb9\u0cb0\u0cbf\u0caf\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca4\u0ccd\u0ca4\u0cc1. \u0c8e\u0cb0\u0ca1\u0cc1 \u0c92\u0ca6\u0ccd\u0ca6\u0cc6 \u0c95\u0cb2\u0ccd\u0cb2\u0cc1\u0c97\u0cb3 \u0ca8\u0ca1\u0cc1\u0cb5\u0cc6 \u0cb9\u0cc6\u0cb8\u0cb0\u0cbf\u0cb2\u0ccd\u0cb2\u0ca6 \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95 \u0cb8\u0cbf\u0c95\u0ccd\u0c95\u0cbf\u0ca4\u0cc1. \u0cae\u0cca\u0ca6\u0cb2 \u0caa\u0cc1\u0c9f \u0ca4\u0cc6\u0cb0\u0cc6\u0ca6\u0cbe\u0c97 \u0c85\u0ca6\u0cc1 \u0c85\u0cb5\u0cb0 \u0cad\u0cbe\u0cb7\u0cc6\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0cae\u0cbe\u0ca4\u0ca8\u0cbe\u0ca1\u0cbf\u0ca4\u0cc1. \u0cae\u0cc1\u0c82\u0ca6\u0cbf\u0ca8 \u0caa\u0cc1\u0c9f \u0cac\u0ca6\u0cb2\u0cbe\u0caf\u0cbf\u0ca4\u0cc1.",
    "\u0ca8\u0cc2\u0cb0\u0ccd \u0cae\u0cbe\u0cb5\u0cbf\u0ca8 \u0cae\u0cb0\u0ca6 \u0c95\u0cc6\u0cb3\u0c97\u0cc6 \u0c95\u0cc1\u0cb3\u0cbf\u0ca4\u0cc1 \u0c93\u0ca6\u0cbf\u0ca6. \u0c92\u0cac\u0ccd\u0cac \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0\u0cbf \u0c8f\u0ca8\u0cc1 \u0c93\u0ca6\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0ccd\u0ca6\u0cc0\u0cb0\u0cbf \u0c8e\u0c82\u0ca6\u0cc1 \u0c95\u0cc7\u0cb3\u0cbf\u0ca6. \u0ca8\u0cc2\u0cb0\u0ccd \u0cb9\u0cc7\u0cb3\u0cbf\u0ca6, \u0c87\u0ca6\u0cc1 \u0c92\u0c82\u0ca6\u0cc1 \u0cad\u0cbe\u0cb7\u0cc6\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0c87\u0cb0\u0cb2\u0cc1 \u0ca8\u0cbf\u0cb0\u0cbe\u0c95\u0cb0\u0cbf\u0cb8\u0cc1\u0cb5 \u0c95\u0ca5\u0cc6. \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbe\u0cb0\u0cbf \u0ca8\u0c95\u0ccd\u0c95. \u0ca8\u0c82\u0ca4\u0cb0 \u0c95\u0cbe\u0c97\u0ca6\u0ca6\u0cbf\u0c82\u0ca6 \u0c85\u0c9c\u0ccd\u0c9c\u0cbf\u0caf \u0ca7\u0ccd\u0cb5\u0ca8\u0cbf \u0c8f\u0cb3\u0cbf\u0ca4\u0cc1.",
    "\u0c85\u0cb5\u0cb0\u0cc1 \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95\u0cb5\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca8\u0c97\u0cb0\u0ca6\u0cbe\u0ca6\u0ccd\u0caf\u0c82\u0ca4 \u0ca4\u0cc6\u0c97\u0cc6\u0ca6\u0cc1\u0c95\u0cca\u0c82\u0ca1\u0cc1 \u0cb9\u0ccb\u0ca6\u0cb0\u0cc1. \u0c9f\u0cc0 \u0c85\u0c82\u0c97\u0ca1\u0cbf\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0c92\u0cac\u0ccd\u0cac \u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0cb0\u0ccd\u0ca5\u0cbf \u0ca8\u0c95\u0ccd\u0c95. \u0ca8\u0cbf\u0cb2\u0ccd\u0ca6\u0cbe\u0ca3\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c92\u0cac\u0ccd\u0cac \u0caa\u0ccd\u0cb0\u0caf\u0cbe\u0ca3\u0cbf\u0c95 \u0c95\u0ca3\u0ccd\u0ca3\u0cc1 \u0cae\u0cc1\u0c9a\u0ccd\u0c9a\u0cbf \u0c95\u0cc7\u0cb3\u0cbf\u0ca6. \u0c89\u0ca6\u0ccd\u0caf\u0cbe\u0ca8\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c92\u0cac\u0ccd\u0cac \u0cb5\u0cc3\u0ca6\u0ccd\u0ca7\u0cc6 \u0ca8\u0cc2\u0cb0\u0ccd\u0c97\u0cbf\u0c82\u0ca4 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0cb5\u0cbe\u0c95\u0ccd\u0caf \u0cae\u0cc1\u0c97\u0cbf\u0cb8\u0cbf\u0ca6\u0cb3\u0cc1.",
    "\u0cb8\u0c82\u0c9c\u0cc6\u0caf \u0cb5\u0cc7\u0cb3\u0cc6\u0c97\u0cc6 \u0c95\u0cca\u0ca8\u0cc6\u0caf \u0caa\u0cc1\u0c9f \u0cac\u0cb9\u0cc1\u0ca4\u0cc7\u0c95 \u0c96\u0cbe\u0cb2\u0cbf\u0caf\u0cbe\u0c97\u0cbf\u0ca4\u0ccd\u0ca4\u0cc1. \u0c92\u0c82\u0ca6\u0cc1 \u0cb8\u0cbe\u0cb2\u0cc1 \u0cae\u0cbe\u0ca4\u0ccd\u0cb0 \u0c89\u0cb3\u0cbf\u0ca6\u0cbf\u0ca4\u0ccd\u0ca4\u0cc1. \u0ca8\u0cc0\u0ca8\u0cc1 \u0caa\u0ccd\u0cb0\u0cc0\u0ca4\u0cbf\u0cb8\u0cc1\u0cb5 \u0cad\u0cbe\u0cb7\u0cc6\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0cae\u0cc1\u0c82\u0ca6\u0cbf\u0ca8 \u0caa\u0cc1\u0c9f \u0cac\u0cb0\u0cc6. \u0ca8\u0cc2\u0cb0\u0ccd \u0ca8\u0cbf\u0ca7\u0cbe\u0ca8\u0cb5\u0cbe\u0c97\u0cbf \u0cac\u0cb0\u0cc6\u0ca6. \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95 \u0cae\u0cc1\u0c9a\u0ccd\u0c9a\u0cbf\u0ca6\u0cbe\u0c97 \u0ca8\u0ca6\u0cbf \u0cb8\u0cbe\u0cb5\u0cbf\u0cb0 \u0ca7\u0ccd\u0cb5\u0ca8\u0cbf\u0c97\u0cb3\u0c82\u0ca4\u0cc6 \u0c95\u0cc7\u0cb3\u0cbf\u0cb8\u0cbf\u0ca4\u0cc1.",
    "\u0c86 \u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbf \u0cae\u0cbe\u0cb0\u0cc1\u0c95\u0c9f\u0ccd\u0c9f\u0cc6\u0caf \u0ca6\u0cc0\u0caa\u0c97\u0cb3\u0cc1 \u0c95\u0ca4\u0ccd\u0ca4\u0cb2\u0cc6\u0caf \u0cae\u0cc7\u0cb2\u0cc6 \u0cb5\u0cbf\u0cb0\u0cbe\u0cae \u0c9a\u0cbf\u0cb9\u0ccd\u0ca8\u0cc6\u0c97\u0cb3\u0c82\u0ca4\u0cc6 \u0c95\u0cbe\u0ca3\u0cbf\u0cb8\u0cbf\u0ca6\u0cb5\u0cc1. \u0ca8\u0cc2\u0cb0\u0ccd \u0c92\u0c82\u0ca6\u0cc1 \u0cb8\u0cb0\u0cb3 \u0cb8\u0ca4\u0ccd\u0caf\u0cb5\u0ca8\u0ccd\u0ca8\u0cc1 \u0c85\u0cb0\u0cbf\u0ca4. \u0caa\u0ca6\u0c97\u0cb3\u0cc1 \u0cae\u0cc1\u0c97\u0cbf\u0ca6\u0cbe\u0c97 \u0c95\u0ca5\u0cc6 \u0cae\u0cc1\u0c97\u0cbf\u0caf\u0cc1\u0cb5\u0cc1\u0ca6\u0cbf\u0cb2\u0ccd\u0cb2. \u0c87\u0ca8\u0ccd\u0ca8\u0cca\u0cac\u0ccd\u0cac\u0cb0\u0cc1 \u0c95\u0cc7\u0cb3\u0cbf \u0c89\u0ca4\u0ccd\u0ca4\u0cb0\u0cbf\u0cb8\u0cac\u0cb9\u0cc1\u0ca6\u0cbe\u0ca6\u0cbe\u0c97\u0cb2\u0cc7 \u0c95\u0ca5\u0cc6 \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0cb5\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6.",
]


def php_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace("'", "\\'")


def story_block(sid, name, native, font, title, paragraphs) -> str:
    lines = [
        "    [",
        f"        'id' => '{sid}',",
        f"        'name' => '{name}',",
        f"        'native' => '{php_escape(native)}',",
        "        'dir' => 'ltr',",
        f"        'font' => '{font}',",
        f"        'title' => '{php_escape(title)}',",
        "        'paragraphs' => [",
    ]
    for para in paragraphs:
        lines.append(f"            '{php_escape(para)}',")
    lines.extend(["        ],", "    ],"])
    return "\n".join(lines)


blocks = "\n".join(
    [
        story_block("te", "Telugu", "\u0c24\u0c46\u0c32\u0c41\u0c17\u0c41", "Noto Sans Telugu", te_title, te),
        story_block("ml", "Malayalam", "\u0d2e\u0d32\u0d2f\u0d3e\u0d33\u0d02", "Noto Sans Malayalam", ml_title, ml),
        story_block("gu", "Gujarati", "\u0a97\u0ac1\u0a9c\u0ab0\u0abe\u0aa4\u0ac0", "Noto Sans Gujarati", gu_title, gu),
        story_block("pa", "Punjabi", "\u0a2a\u0a70\u0a1c\u0a3e\u0a2c\u0a40", "Noto Sans Gurmukhi", pa_title, pa),
        story_block("kn", "Kannada", "\u0c95\u0ca8\u0ccd\u0ca8\u0ca1", "Noto Sans Kannada", kn_title, kn),
    ]
)

root = Path(__file__).resolve().parents[1]
main = root / "resources" / "stories" / "all-languages.php"
text = main.read_text(encoding="utf-8")
start = text.index("        'id' => 'te',")
start = text.rindex("    [", 0, start)
end = text.index("        'id' => 'mr',")
end = text.rindex("    [", 0, end)
main.write_text(text[:start] + blocks + "\n" + text[end:], encoding="utf-8")
print("patched", main, "bytes", main.stat().st_size)
